import{d as r,C as s,o as d,c as g,a3 as t,E as e,j as a,a as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第十七章","description":"《正易心法》第十七章——六十四卦，皆有取象：屯象草木、蒙象童稚……名义无不反对；不知取象与反对，是为学《易》之大病。","frontmatter":{"title":"正易心法·第十七章","description":"《正易心法》第十七章——六十四卦，皆有取象：屯象草木、蒙象童稚……名义无不反对；不知取象与反对，是为学《易》之大病。","category":"guide","aliases":["正易心法第十七章","六十四卦皆有取象","名义无不反对"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-17.md","filePath":"yijing/zheng-yi-xin-fa/chapter-17.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-17.md"},x=r({...c,setup(u){const i=[{id:"z17-01",label:"一、取象与名义反对",showLabel:!0,sentences:[["六十四卦，皆有",{text:"取象",glossary:"quxiang"},"。其为",{text:"名义",glossary:"mingyi"},"，无不反对。"]],note:["六十四卦都有取象，其卦名与含义无不构成反对关系。（这是第十六章「反对密意」的具体展开：前者说反对是圣人的密意，本章说六十四卦的**名义**无不反对——**结构（反对卦画）→ 象（取象物象）→ 义（名义反对），三个层次一贯。**）"]},{id:"z17-02",label:"二、易者象也",showLabel:!0,sentences:[["《易》之取象，世所知者数卦而已，如颐、如鼎、如噬嗑之类是。殊不知《易》者，象也，依物象以为训，古六十四卦皆有取象。"]],note:["《易》的取象，世人只知道几个卦，如颐（卦画像口）、鼎（卦画像鼎）、噬嗑（卦画像口中有物）之类。殊不知《易》就是象，依据具体物象来解释，古来六十四卦都有取象。（**「《易》者，象也」是本章的核心命题**：辞是用来说明象的，象才是本体。所以正确顺序是：先看卦画（象）→ 再看取象（物象）→ 再看卦辞（文字）。）"]},{id:"z17-03",label:"三、六十四卦皆有取象",showLabel:!0,sentences:[["如屯象草木，蒙象童稚，需象燕宾，讼象饮食，师象军阵，比象翼戴，家人象家正，睽象覆家，余卦尽然。"]],note:["比如：屯象草木初生，蒙象幼童蒙昧，需象宴请宾客，讼象饮食争讼，师象军队阵列，比象辅翼拥戴，家人象家道端正，睽象家道倾覆——其余各卦都是这样。（这些不是随意比喻，而是**从卦画结构直接读出来的**：屯☷☳上坎下震，震（动）在下如种子萌动，坎（险）在上如土壤压覆——故象草木破土之艰难。）"]},{id:"z17-04",label:"四、名义反对之例",showLabel:!0,sentences:[["一人诸卦，名义无不反对。如噬嗑以",{text:"贪饕",glossary:"tantao"},"，贲以节饰，履以蹈艰危，小畜以享尊富，临以出而治人，观以入而处己，丰以富盛，旅以困穷。"]],note:["将诸卦一一对应，卦名与含义无不构成反对关系：噬嗑象贪婪吞食，贲象节制文饰；履象踩踏艰危，小畜象享受尊富；临象出外治人，观象退入处己；丰象富足盛大，旅象困顿穷乏。（**每一对都是一放一收、一苦一乐、一出（入）一盛一衰**——卦名的反对，就是现实的反对。）"]},{id:"z17-05",label:"五、学易之大病",showLabel:!0,sentences:[["自余推之，其名义反对，无不然者，此学《易》之大",{text:"病",glossary:"dabing"},"也。"]],note:["从其余各卦推演，其名义的反对关系无不如此。**不知此理，正是学习《易》的大毛病。**（「大病」是全书对错误最重的定性之一——因为不知取象是**不知《易》是象**（根本错误），不知反对是**不知吉凶一体**（哲学错误），两个根本错误叠加，就成了「大病」。与第一章「不知落处，则玩占亦虚语」完全同调。）"]}],o=[{id:"quxiang",term:"取象",pinyin:"qǔ xiàng",meaning:"取用具体物象。每个卦名都有其对应的具体物象，非随意比喻，而是从卦画结构读出。"},{id:"mingyi",term:"名义",pinyin:"míng yì",meaning:"卦名与含义。六十四卦的名义无不构成反对关系。"},{id:"tantao",term:"贪饕",pinyin:"tān tāo",meaning:"贪食。饕是贪食之兽。噬嗑象口中有物强行咬合，故有贪婪之象。"},{id:"dabing",term:"大病",pinyin:"dà bìng",meaning:"根本性的错误。不知取象＝不知《易》是象；不知反对＝不知吉凶一体。两个根本错误叠加。"}];return(b,n)=>{const l=s("DaoTextReading"),p=s("DaoKeywordCards");return d(),g("div",null,[n[0]||(n[0]=t("",20)),e(l,{colophon:"皆有取象 · 易者象也 · 名义反对 · 学易大病",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第十七章原文",sections:i,glossary:o}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入，用字随底本（原文「一人诸卦」之「一人」当作「一一」解，谓逐一排列诸卦），不作统一。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(p,{items:[{term:"易者象也",pinyin:["yì","zhě"],meaning:"本章核心命题：辞是用来说明象的，象才是本体。正确顺序是卦画 → 取象 → 卦辞。"},{term:"六十四卦皆有取象",pinyin:["qǔ","xiàng"],meaning:"屯象草木、蒙象童稚、需象燕宾、讼象饮食、师象军阵、比象翼戴、家人象家正、睽象覆家……余卦尽然。"},{term:"名义无不反对",pinyin:["míng","yì"],meaning:"噬嗑（贪饕）↔贲（节饰）；履（蹈艰危）↔小畜（享尊富）；临（出而治人）↔观（入而处己）；丰（富盛）↔旅（困穷）。"},{term:"学易之大病",pinyin:["dà","bìng"],meaning:"不知取象＝不知《易》是象；不知反对＝不知吉凶一体。两个根本错误叠加，故曰「大病」。"}]}),n[3]||(n[3]=t("",26))])}}});export{y as __pageData,x as default};
